def _known_bool(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return value
    return None


def _known_number(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _bool_options(value):
    if isinstance(value, bool):
        return [value]
    return [False, True]


def _tri_and(values):
    for value in values:
        if value is False:
            return False
    for value in values:
        if value is None:
            return None
    return True


def _tri_or(values):
    for value in values:
        if value is True:
            return True
    for value in values:
        if value is None:
            return None
    return False


def _unique(values):
    result = []
    for value in values:
        if value not in result:
            result.append(value)
    return result


def _subject(question):
    match = re.search(r"applies\s+to\s+([A-Z][A-Za-z'-]*)", question)
    if match:
        return match.group(1)
    match = re.search(r"([A-Z][A-Za-z'-]*)(?:'s|’s)\s+additional\s+standard\s+deduction", question)
    if match:
        return match.group(1)
    return "the taxpayer"


def _kind(question):
    lower = question.lower()
    c6 = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*6\s*\)\s*\(\s*a\s*\)", question, re.I)
    c3 = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*3\s*\)", question, re.I)
    if c6 and ("apply" in lower or "applies" in lower or "applicable" in lower or "inapplicable" in lower):
        return "c6a"
    if c3 or "additional standard deduction" in lower:
        if _money_claim(question) is not None:
            return "c3_amount"
    return "unsupported"


def _plan_c6a(subject):
    return {
        "taxpayer_married": {"type": "boolean", "question": "Was " + subject + " married at the relevant close-of-year time stated in the case?"},
        "legally_separated_under_decree": {"type": "boolean", "question": "Was " + subject + " legally separated from the spouse under a decree of divorce or separate maintenance?"},
        "filed_separate_return": {"type": "boolean", "question": "Did " + subject + " file a separate return for the taxable year?"},
        "taxpayer_itemized_deductions": {"type": "boolean", "question": "Did " + subject + " itemize deductions for the taxable year?"},
        "spouse_itemized_deductions": {"type": "boolean", "question": "Did " + subject + "'s spouse itemize deductions for the taxable year?"}
    }


def _plan_c3(subject):
    return {
        "stated_f1a_self_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + subject + " is entitled to for " + subject + " under section 63(f)(1)(A)?"},
        "stated_f1b_spouse_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + subject + " is entitled to for the spouse under section 63(f)(1)(B)?"},
        "stated_f2a_self_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + subject + " is entitled to for " + subject + " under section 63(f)(2)(A)?"},
        "stated_f2b_spouse_amount": {"type": "number", "question": "What dollar amount does the case explicitly state " + subject + " is entitled to for the spouse under section 63(f)(2)(B)?"},
        "stated_additional_standard_deduction_total": {"type": "number", "question": "What total additional standard deduction amount, if any, does the case explicitly state for " + subject + "?"},
        "taxpayer_married": {"type": "boolean", "question": "Was " + subject + " married at the relevant close-of-year time stated in the case?"},
        "legally_separated_under_decree": {"type": "boolean", "question": "Was " + subject + " legally separated from the spouse under a decree of divorce or separate maintenance?"},
        "spouse_died_in_either_prior_two_years": {"type": "boolean", "question": "Did " + subject + "'s spouse die during either of the two years immediately preceding the taxable year?"},
        "maintained_home_for_listed_child_dependent": {"type": "boolean", "question": "Did " + subject + " maintain a home that was the taxable-year principal abode of a dependent son, stepson, daughter, or stepdaughter?"},
        "furnished_over_half_home_cost": {"type": "boolean", "question": "Did " + subject + " furnish over half the cost of maintaining that household during the taxable year?"},
        "remarried_before_year_end": {"type": "boolean", "question": "Had " + subject + " remarried before the close of the taxable year?"},
        "death_year_joint_return_possible": {"type": "boolean", "question": "Could " + subject + " and the deceased spouse have made a joint return for the taxable year in which the spouse died?"},
        "taxpayer_attained_65_before_close": {"type": "boolean", "question": "Had " + subject + " attained age 65 before the close of the taxable year?"},
        "taxpayer_blind_at_close": {"type": "boolean", "question": "Was " + subject + " blind at the close of the taxable year?"},
        "spouse_attained_65_before_close": {"type": "boolean", "question": "Had " + subject + "'s spouse attained age 65 before the close of the taxable year?"},
        "spouse_blind_at_required_time": {"type": "boolean", "question": "Was " + subject + "'s spouse blind at the close of the taxable year, or at death if the spouse died during that year?"},
        "joint_return_made": {"type": "boolean", "question": "Did " + subject + " and the spouse make a joint return?"},
        "spouse_had_no_gross_income": {"type": "boolean", "question": "Did " + subject + "'s spouse have no gross income for the relevant calendar year?"},
        "spouse_dependent_of_another_taxpayer": {"type": "boolean", "question": "Was " + subject + "'s spouse the dependent of another taxpayer for the relevant calendar year?"}
    }


def _married_status(facts):
    separated = _known_bool(facts, "legally_separated_under_decree")
    married = _known_bool(facts, "taxpayer_married")
    if separated is True:
        return False
    if isinstance(married, bool):
        return married
    return None


def _surviving_status(facts):
    remarried = _known_bool(facts, "remarried_before_year_end")
    not_remarried = None if remarried is None else not remarried
    return _tri_and([
        _known_bool(facts, "spouse_died_in_either_prior_two_years"),
        _known_bool(facts, "maintained_home_for_listed_child_dependent"),
        _known_bool(facts, "furnished_over_half_home_cost"),
        not_remarried,
        _known_bool(facts, "death_year_joint_return_possible")
    ])


def _spouse_exemption_options(facts):
    joint = _bool_options(_known_bool(facts, "joint_return_made"))
    no_income = _bool_options(_known_bool(facts, "spouse_had_no_gross_income"))
    dependent = _bool_options(_known_bool(facts, "spouse_dependent_of_another_taxpayer"))
    answers = set()
    for j in joint:
        for n in no_income:
            for d in dependent:
                answers.add((not j) and n and (not d))
    return sorted(answers)


def _c6a_status(facts):
    married = _married_status(facts)
    separate = _known_bool(facts, "filed_separate_return")
    either_itemizes = _tri_or([
        _known_bool(facts, "taxpayer_itemized_deductions"),
        _known_bool(facts, "spouse_itemized_deductions")
    ])
    result = _tri_and([married, separate, either_itemizes])
    if result is not None:
        return result, []
    dependencies = []
    if married is None:
        if _known_bool(facts, "taxpayer_married") is None:
            dependencies.append("taxpayer_married")
        if _known_bool(facts, "legally_separated_under_decree") is None:
            dependencies.append("legally_separated_under_decree")
    if separate is None:
        dependencies.append("filed_separate_return")
    if either_itemizes is None:
        if _known_bool(facts, "taxpayer_itemized_deductions") is None:
            dependencies.append("taxpayer_itemized_deductions")
        if _known_bool(facts, "spouse_itemized_deductions") is None:
            dependencies.append("spouse_itemized_deductions")
    return None, dependencies


def _given_component_total(facts):
    specifications = [
        ("stated_f1a_self_amount", "R63_F1_AGED"),
        ("stated_f1b_spouse_amount", "R63_F1_AGED"),
        ("stated_f2a_self_amount", "R63_F2_BLIND"),
        ("stated_f2b_spouse_amount", "R63_F2_BLIND")
    ]
    values = []
    rules = ["R63_C3"]
    for key, rule_id in specifications:
        value = _known_number(facts, key)
        if value is not None:
            values.append(value)
            rules.append(rule_id)
    if len(values) > 0:
        return sum(values), _unique(rules), True
    total = _known_number(facts, "stated_additional_standard_deduction_total")
    if total is not None:
        return total, ["R63_C3"], True
    return None, [], False


def _derived_additional_values(facts):
    married_options = _bool_options(_married_status(facts))
    surviving_options = _bool_options(_surviving_status(facts))
    aged_options = _bool_options(_known_bool(facts, "taxpayer_attained_65_before_close"))
    blind_options = _bool_options(_known_bool(facts, "taxpayer_blind_at_close"))
    spouse_aged_options = _bool_options(_known_bool(facts, "spouse_attained_65_before_close"))
    spouse_blind_options = _bool_options(_known_bool(facts, "spouse_blind_at_required_time"))
    exemption_options = _spouse_exemption_options(facts)
    amounts = set()
    for married in married_options:
        for surviving in surviving_options:
            rate = 750 if (not married and not surviving) else 600
            for aged in aged_options:
                for blind in blind_options:
                    if married:
                        for spouse_aged in spouse_aged_options:
                            for spouse_blind in spouse_blind_options:
                                for exemption in exemption_options:
                                    count = int(aged) + int(blind)
                                    count = count + int(spouse_aged and exemption)
                                    count = count + int(spouse_blind and exemption)
                                    amounts.add(rate * count)
                    else:
                        amounts.add(rate * (int(aged) + int(blind)))
    dependencies = []
    if len(amounts) > 1:
        if _married_status(facts) is None:
            if _known_bool(facts, "taxpayer_married") is None:
                dependencies.append("taxpayer_married")
            if _known_bool(facts, "legally_separated_under_decree") is None:
                dependencies.append("legally_separated_under_decree")
        if False in married_options and _surviving_status(facts) is None:
            for key in ["spouse_died_in_either_prior_two_years", "maintained_home_for_listed_child_dependent", "furnished_over_half_home_cost", "remarried_before_year_end", "death_year_joint_return_possible"]:
                if _known_bool(facts, key) is None:
                    dependencies.append(key)
        for key in ["taxpayer_attained_65_before_close", "taxpayer_blind_at_close"]:
            if _known_bool(facts, key) is None:
                dependencies.append(key)
        if True in married_options:
            for key in ["spouse_attained_65_before_close", "spouse_blind_at_required_time"]:
                if _known_bool(facts, key) is None:
                    dependencies.append(key)
            spouse_may_qualify = (_known_bool(facts, "spouse_attained_65_before_close") is not False or _known_bool(facts, "spouse_blind_at_required_time") is not False)
            if spouse_may_qualify:
                for key in ["joint_return_made", "spouse_had_no_gross_income", "spouse_dependent_of_another_taxpayer"]:
                    if _known_bool(facts, key) is None:
                        dependencies.append(key)
    rules = ["R63_C3", "R63_F1_AGED", "R63_F2_BLIND", "R63_F3_RATE", "R7703_SEPARATION"]
    if False in married_options:
        rules.extend(["R2_SURVIVING_CORE", "R2_SURVIVING_HOME", "R2_SURVIVING_LIMITS"])
    if True in married_options:
        rules.append("R151_B_SPOUSE")
    return sorted(amounts), _unique(dependencies), _unique(rules)


def _additional_values(facts):
    total, rules, supplied = _given_component_total(facts)
    if supplied:
        return [total], [], rules
    return _derived_additional_values(facts)


def _money_claim(question):
    match = re.search(r"\$\s*([0-9][0-9,]*(?:\.[0-9]+)?)", question)
    if not match:
        match = re.search(r"([0-9][0-9,]*(?:\.[0-9]+)?)\s+dollars?", question, re.I)
    if not match:
        return None
    return float(match.group(1).replace(",", ""))


def _apply_negated(question):
    return bool(re.search(r"(?:does|did|is)\s+not\s+apply|doesn't\s+apply|inapplicable", question, re.I))


def _amount_negated(question):
    return bool(re.search(r"not\s+(?:be\s+)?equal|does\s+not\s+equal|isn't\s+equal|unequal|additional\s+standard\s+deduction[^.]{0,80}\bis\s+not\s+\$", question, re.I))


def _label(truth, negated):
    if truth is None:
        return "unknown"
    if negated:
        truth = not truth
    return "Entailment" if truth else "Contradiction"


def apply(inputs, premises):
    if not isinstance(inputs, dict):
        return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["inputs must be an object"]}
    phase = inputs.get("phase", "")
    question = str(inputs.get("question", ""))
    kind = _kind(question)
    if phase == "plan":
        subject = _subject(question)
        if kind == "c6a":
            return {"supported": True, "fields": _plan_c6a(subject)}
        if kind == "c3_amount":
            return {"supported": True, "fields": _plan_c3(subject)}
        return {"supported": False, "fields": {}}
    if phase != "evaluate":
        return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["phase must be plan or evaluate"]}
    facts = inputs.get("facts", {})
    if not isinstance(facts, dict):
        facts = {}
    if kind == "c6a":
        truth, dependencies = _c6a_status(facts)
        return {
            "answer": _label(truth, _apply_negated(question)),
            "used_rule_ids": ["R63_C6A", "R7703_SEPARATION"],
            "open_dependencies": dependencies if truth is None else []
        }
    if kind == "c3_amount":
        target = _money_claim(question)
        if target is None:
            return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["claimed dollar amount"]}
        values, dependencies, rules = _additional_values(facts)
        truth = None
        if len(values) == 1:
            truth = values[0] == target
        elif target not in values:
            truth = False
        return {
            "answer": _label(truth, _amount_negated(question)),
            "used_rule_ids": rules,
            "open_dependencies": dependencies if truth is None else []
        }
    return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["unsupported statutory claim form"]}
